"""The eval manifest: the traceability spine every gate reads.

The bridge is the only writer. The manifest maps scenario to eval case
to compiled check, and the verifier proves bidirectional coverage:
every scenario has an eval case, and every eval case cites a scenario.
"""

import json
from pathlib import Path

from . import compile as compile_mod

GENERATED_MARKER = (
    "GENERATED by python -m dspy_gate regen; edit the spec, not this file."
)
RUNNER_GATES = {"dspy-eval": [2, 3]}


def build(parsed_change, modules):
    """Build the manifest dict for one parsed change.

    modules is the harness registry: capability -> module entry with
    impl, entry or artifacts, and optional example inputs. The registry
    is the opt-in contract: scenarios of a capability it does not
    declare stay outside the manifest with the ordinary suite.
    """
    cases = []
    modules_out = {}
    for requirement in parsed_change["requirements"]:
        for scenario in requirement["scenarios"]:
            if scenario["capability"] not in modules:
                continue
            module = modules[scenario["capability"]]
            modules_out.setdefault(
                scenario["capability"],
                {
                    "module": module["module"],
                    "impl": module["impl"],
                    "entry": module.get("entry", ""),
                    "artifacts": module.get("artifacts", ""),
                    "scenarios": [],
                },
            )
            modules_out[scenario["capability"]]["scenarios"].append(
                scenario["scenario_id"]
            )
            cases.append(
                {
                    "scenario_id": scenario["scenario_id"],
                    "capability": scenario["capability"],
                    "surface": scenario["surface"],
                    "runner": scenario["surface"],
                    "gates": RUNNER_GATES.get(scenario["surface"], [3]),
                    "dataset_path": dataset_relpath(scenario),
                    "checks": compile_mod.compile_scenario(scenario),
                    "judged": scenario["judged"],
                    "rubric": scenario.get("rubric"),
                    "source_hash": scenario["source_hash"],
                    "when": scenario["when"],
                    "thens": scenario["thens"],
                }
            )
    return {
        "version": 1,
        "_generated": GENERATED_MARKER,
        "changes": {
            parsed_change["change_id"]: {
                "modules": list(modules_out.values()),
                "eval_cases": cases,
            }
        },
    }


def dataset_relpath(scenario):
    """The change-relative dataset path for one scenario."""
    return f"evals/{scenario['capability']}/{scenario['scenario_id']}.json"


def verify(data, parsed_change, modules=None):
    """Return the bidirectional coverage violations (Gate 1).

    With a registry, only its capabilities count: the governed set is
    the opt-in set.
    """
    change = data["changes"][parsed_change["change_id"]]
    case_ids = [c["scenario_id"] for c in change["eval_cases"]]
    spec_ids = [
        s["scenario_id"]
        for r in parsed_change["requirements"]
        for s in r["scenarios"]
        if modules is None or s["capability"] in modules
    ]
    found = []
    for sid in spec_ids:
        if sid not in case_ids:
            found.append(f"scenario {sid} has no eval case")
    for cid in case_ids:
        if cid not in spec_ids:
            found.append(f"eval case {cid} cites no scenario in the change")
    return found


def write(data, path):
    """Write the manifest JSON with a trailing newline."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def load(path):
    """Read the manifest JSON."""
    with Path(path).open(encoding="utf-8") as handle:
        return json.load(handle)
